-- Approved WASM programs can only propose a new salary-parameter version.
-- They never create wage lines, economic obligations, confirmations or payments.
CREATE TABLE ty_ps_script(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL,
 code text NOT NULL CHECK(code~'^[A-Za-z][A-Za-z0-9_]{2,63}$'),name text NOT NULL,
 revision integer NOT NULL CHECK(revision>0),system text NOT NULL CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),
 valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>valid_from),
 source text NOT NULL CHECK(octet_length(source)BETWEEN 1 AND 65536),source_hash text NOT NULL CHECK(source_hash~'^[a-f0-9]{64}$'),
 input_spec jsonb NOT NULL CHECK(jsonb_typeof(input_spec)='object'),output_spec jsonb NOT NULL CHECK(jsonb_typeof(output_spec)='object'),
 engine jsonb NOT NULL,evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),UNIQUE(company_id,code,revision)
);
CREATE TABLE ty_ps_run(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,script_id bigint NOT NULL REFERENCES ty_ps_script(id),
 group_id bigint NOT NULL,company_id bigint NOT NULL,person_id bigint NOT NULL,employment_id bigint NOT NULL,
 period date NOT NULL CHECK(extract(day FROM period)=1),base_profile_id bigint NOT NULL REFERENCES ty_pay_config(id),
 base_hash text NOT NULL,base_snapshot jsonb NOT NULL,relationship_id bigint NOT NULL REFERENCES ty_pay_config(id),relationship_snapshot jsonb NOT NULL,
 report_id bigint REFERENCES ty_time_report_version(id),report_root_id bigint REFERENCES ty_time_report_root(id),report_head_revision integer,
 input_snapshot jsonb NOT NULL,input_hash text NOT NULL,output_snapshot jsonb,output_hash text,
 merged_data jsonb,engine jsonb NOT NULL,code_hash text NOT NULL,
 status text NOT NULL CHECK(status IN('completed','failed')),error_code text,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),
 CHECK((status='completed')=(output_snapshot IS NOT NULL AND output_hash IS NOT NULL AND merged_data IS NOT NULL)),
 CHECK((report_id IS NULL)=(report_root_id IS NULL)),CHECK((report_id IS NULL)=(report_head_revision IS NULL))
);
CREATE TABLE ty_ps_origin(
 profile_config_id bigint PRIMARY KEY REFERENCES ty_pay_config(id),run_id bigint NOT NULL UNIQUE REFERENCES ty_ps_run(id),
 base_profile_id bigint NOT NULL REFERENCES ty_pay_config(id),base_hash text NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ty_ps_trigger(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,script_id bigint NOT NULL REFERENCES ty_ps_script(id),
 group_id bigint NOT NULL,company_id bigint NOT NULL,employment_id bigint NOT NULL,person_id bigint NOT NULL,
 event_kind text NOT NULL CHECK(event_kind IN('manual','time_report.confirmed','salary_profile.approved')),
 valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>valid_from),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),revision integer NOT NULL DEFAULT 1,
 evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),created_by bigint NOT NULL REFERENCES sys_account(id),
 approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),
 FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id)
);
CREATE TABLE ty_ps_job(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,trigger_id bigint NOT NULL REFERENCES ty_ps_trigger(id),
 event_key text NOT NULL,source_domain text NOT NULL CHECK(source_domain IN('manual','time_report','salary_profile')),
 source_id bigint,source_revision text,period date NOT NULL CHECK(extract(day FROM period)=1),report_id bigint REFERENCES ty_time_report_version(id),
 state text NOT NULL DEFAULT'queued'CHECK(state IN('queued','completed','blocked','cancelled')),revision integer NOT NULL DEFAULT 1,
 run_id bigint REFERENCES ty_ps_run(id),created_by bigint NOT NULL REFERENCES sys_account(id),processed_by bigint REFERENCES sys_account(id),
 reason text,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,
 UNIQUE(trigger_id,event_key),CHECK(state<>'completed'OR run_id IS NOT NULL)
);
CREATE TABLE ty_ps_ai_proposal(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,
 purpose text NOT NULL CHECK(purpose IN('draft_script','explain_run')),request jsonb NOT NULL,proposal jsonb NOT NULL,
 script_id bigint REFERENCES ty_ps_script(id),run_id bigint REFERENCES ty_ps_run(id),
 execution_state text NOT NULL DEFAULT'not_executed'CHECK(execution_state='not_executed'),
 model_connected boolean NOT NULL DEFAULT false CHECK(model_connected=false),
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id)
);
CREATE FUNCTION fn_ty_ps_keep()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资脚本版本、执行快照和参数血缘不得改写或删除';END;$$;
CREATE TRIGGER ty_ps_run_keep BEFORE UPDATE OR DELETE ON ty_ps_run FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_keep();
CREATE TRIGGER ty_ps_origin_keep BEFORE UPDATE OR DELETE ON ty_ps_origin FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_keep();
CREATE TRIGGER ty_ps_ai_keep BEFORE UPDATE OR DELETE ON ty_ps_ai_proposal FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_keep();
CREATE FUNCTION fn_ty_ps_version_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE s public.ty_ps_script%ROWTYPE;e public.ty_employment%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='脚本及触发器保留历史';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['status','approved_by','approved_at','revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','approved_by','approved_at','revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='修改脚本或触发器内容必须新建版本';END IF;
 IF TG_OP='UPDATE'AND NOT(OLD.status='draft'AND NEW.status='approved'OR OLD.status='approved'AND NEW.status='disabled')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='脚本或触发器状态跃迁无效';END IF;
 IF TG_OP='UPDATE'AND OLD.status='approved'AND(NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='停用不得改写原独立核准人和时点';END IF;
 IF NEW.status='approved'THEN
  IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代码与触发器启用须另一自然人核准';END IF;
 END IF;
 IF TG_TABLE_NAME='ty_ps_trigger'THEN
  SELECT * INTO s FROM public.ty_ps_script WHERE id=NEW.script_id;
  SELECT * INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
  IF s.group_id<>NEW.group_id OR s.company_id<>NEW.company_id OR e.person_id<>NEW.person_id OR NEW.status='approved'AND(s.status<>'approved'OR public.fn_ty_pr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='触发器须引用同范围已核代码和真实关系，受益人不得核准';END IF;
 ELSE
  IF NEW.source_hash IS DISTINCT FROM pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(NEW.source,'UTF8')),'hex')OR NEW.engine->>'name'IS DISTINCT FROM'quickjs-emscripten'OR NEW.engine->>'version'IS DISTINCT FROM'0.32.0'OR NEW.engine->>'physical_memory_bytes'IS DISTINCT FROM'67108864'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代码SHA256与固定隔离引擎版本不符';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_script_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_ps_script FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_version_guard();
CREATE TRIGGER ty_ps_trigger_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_ps_trigger FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_version_guard();
CREATE FUNCTION fn_ty_ps_run_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE s public.ty_ps_script%ROWTYPE;b public.ty_pay_config%ROWTYPE;r public.ty_pay_config%ROWTYPE;e public.ty_employment%ROWTYPE;h public.ty_time_report_root%ROWTYPE;k text;p jsonb;
BEGIN
 SELECT * INTO s FROM public.ty_ps_script WHERE id=NEW.script_id;
 SELECT * INTO b FROM public.ty_pay_config WHERE id=NEW.base_profile_id;
 SELECT * INTO r FROM public.ty_pay_config WHERE id=NEW.relationship_id;
 SELECT * INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF s.status<>'approved'OR s.group_id<>NEW.group_id OR s.company_id<>NEW.company_id OR s.source_hash<>NEW.code_hash OR NEW.engine IS DISTINCT FROM s.engine OR b.kind<>'profile'OR b.status<>'approved'OR b.employment_id<>e.id OR e.person_id<>NEW.person_id OR b.person_id<>NEW.person_id OR b.company_id<>NEW.company_id OR b.group_id<>NEW.group_id OR b.system<>s.system OR r.kind<>'relationship'OR r.status<>'approved'OR r.employment_id<>e.id OR r.system<>s.system OR r.group_id<>NEW.group_id OR NEW.base_snapshot IS DISTINCT FROM to_jsonb(b)OR NEW.relationship_snapshot IS DISTINCT FROM to_jsonb(r)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='脚本预演必须冻结同范围已核代码、真实关系及工资参数';END IF;
 IF NEW.period<s.valid_from OR s.valid_to IS NOT NULL AND(NEW.period+interval'1 month')::date>s.valid_to OR b.valid_from>NEW.period OR b.valid_to IS NOT NULL AND b.valid_to<(NEW.period+interval'1 month')::date OR r.valid_from>NEW.period OR r.valid_to IS NOT NULL AND r.valid_to<(NEW.period+interval'1 month')::date THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代码或工资参数不覆盖本期';END IF;
 IF NEW.status='completed'THEN
  IF jsonb_typeof(NEW.output_snapshot->'parameters')IS DISTINCT FROM'object'OR NEW.output_snapshot-'parameters'<>'{}'::jsonb OR NEW.output_snapshot->'parameters'='{}'::jsonb OR NEW.merged_data-'parameters'IS DISTINCT FROM b.data-'parameters'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='脚本只能提议声明参数，不能改法定核验和其他业务字段';END IF;
  FOR k,p IN SELECT key,value FROM jsonb_each(NEW.output_snapshot->'parameters')LOOP
   IF NOT(s.output_spec?k)OR k~*'(minimum|statutory|native_verified|guard|tax|mpf|contribution|review|non_working_cash|other_work_minutes|classification|qualification|source)'OR NOT(b.data->'parameters'?k)OR jsonb_typeof(p->'value')IS DISTINCT FROM'string'OR(p->>'value')!~'^-?(0|[1-9][0-9]{0,17})(\.[0-9]{1,8})?$'OR p->>'unit'IS DISTINCT FROM s.output_spec->k->>'unit'OR p->>'unit'IS DISTINCT FROM b.data->'parameters'->k->>'unit'OR p-ARRAY['value','unit']<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='输出参数未声明、单位不符、法律保护参数或非十进制文本';END IF;
   IF(s.output_spec->k?'minimum')AND(p->>'value')::numeric<(s.output_spec->k->>'minimum')::numeric OR(s.output_spec->k?'maximum')AND(p->>'value')::numeric>(s.output_spec->k->>'maximum')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='输出超出已核参数边界';END IF;
  END LOOP;
  IF NEW.merged_data IS DISTINCT FROM jsonb_set(b.data,'{parameters}',(b.data->'parameters')||(NEW.output_snapshot->'parameters'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='新参数必须完整保留原参数档案并仅覆盖批准输出';END IF;
 END IF;
 IF NEW.report_id IS NOT NULL THEN
  SELECT * INTO h FROM public.ty_time_report_root WHERE id=NEW.report_root_id;
  IF h.group_id IS DISTINCT FROM NEW.group_id OR h.employment_id IS DISTINCT FROM NEW.employment_id OR h.owner_company_id IS DISTINCT FROM NEW.company_id OR h.perspective IS DISTINCT FROM'employer'OR h.period IS DISTINCT FROM NEW.period OR h.current_report_id IS DISTINCT FROM NEW.report_id OR h.head_revision IS DISTINCT FROM NEW.report_head_revision OR NOT EXISTS(SELECT 1 FROM public.ty_time_report_version v WHERE v.id=NEW.report_id AND v.status='confirmed')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤输入必须当前雇主口径已核月根';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_run_guard BEFORE INSERT ON ty_ps_run FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_run_guard();
CREATE FUNCTION fn_ty_ps_origin_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_ps_run%ROWTYPE;c public.ty_pay_config%ROWTYPE;b public.ty_pay_config%ROWTYPE;
BEGIN
 SELECT * INTO r FROM public.ty_ps_run WHERE id=NEW.run_id;
 SELECT * INTO c FROM public.ty_pay_config WHERE id=NEW.profile_config_id;
 SELECT * INTO b FROM public.ty_pay_config WHERE id=NEW.base_profile_id;
 IF r.status<>'completed'OR r.base_profile_id<>b.id OR r.base_hash<>NEW.base_hash OR c.status<>'draft'OR c.kind<>'profile'OR c.company_id<>r.company_id OR c.employment_id<>r.employment_id OR c.person_id<>r.person_id OR c.group_id<>r.group_id OR c.system<>b.system OR c.data IS DISTINCT FROM r.merged_data OR c.valid_from<>r.period OR c.valid_to IS DISTINCT FROM(r.period+interval'1 month')::date OR c.created_by<>NEW.created_by THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='参数提案必须来自同关系完整WASM快照且仅创建本期工资参数草稿';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_origin_guard BEFORE INSERT ON ty_ps_origin FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_origin_guard();
CREATE FUNCTION fn_ty_ps_profile_approval_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE o public.ty_ps_origin%ROWTYPE;r public.ty_ps_run%ROWTYPE;b public.ty_pay_config%ROWTYPE;latest_id bigint;h public.ty_time_report_root%ROWTYPE;s public.ty_ps_script%ROWTYPE;
BEGIN
 IF NEW.status<>'approved'OR OLD.status='approved'THEN RETURN NEW;END IF;
 SELECT * INTO o FROM public.ty_ps_origin WHERE profile_config_id=NEW.id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT * INTO r FROM public.ty_ps_run WHERE id=o.run_id;
 SELECT * INTO s FROM public.ty_ps_script WHERE id=r.script_id;
 PERFORM id FROM public.ty_company WHERE id=NEW.company_id FOR UPDATE;
 SELECT * INTO b FROM public.ty_pay_config WHERE id=o.base_profile_id;
 SELECT id INTO latest_id FROM public.ty_pay_config WHERE company_id=NEW.company_id AND employment_id=NEW.employment_id AND kind='profile'AND system=NEW.system AND status='approved'AND valid_from<=NEW.valid_from AND(valid_to IS NULL OR valid_to>=NEW.valid_to)ORDER BY revision DESC,id DESC LIMIT 1;
 IF latest_id IS DISTINCT FROM b.id OR to_jsonb(b)IS DISTINCT FROM r.base_snapshot OR NEW.data IS DISTINCT FROM r.merged_data OR s.status<>'approved'OR public.fn_ty_pr_same_actor(r.created_by,NEW.approved_by)OR public.fn_ty_pr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='脚本参数核准时原参数/代码已变或独立复核不成立，请重做预演';END IF;
 SELECT id INTO latest_id FROM public.ty_pay_config WHERE company_id=NEW.company_id AND employment_id=NEW.employment_id AND kind='relationship'AND system=NEW.system AND status='approved'AND valid_from<=NEW.valid_from AND(valid_to IS NULL OR valid_to>=NEW.valid_to)ORDER BY revision DESC,id DESC LIMIT 1;
 IF latest_id IS DISTINCT FROM r.relationship_id OR(SELECT to_jsonb(c)FROM public.ty_pay_config c WHERE id=latest_id)IS DISTINCT FROM r.relationship_snapshot THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='真实雇主及发薪关系已改，请重做预演';END IF;
 IF r.report_id IS NOT NULL THEN
  SELECT * INTO h FROM public.ty_time_report_root WHERE id=r.report_root_id FOR UPDATE;
  IF h.current_report_id IS DISTINCT FROM r.report_id OR h.head_revision IS DISTINCT FROM r.report_head_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核勤当前月根已变，旧脚本参数不能发布';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_profile_approval_guard BEFORE UPDATE ON ty_pay_config FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_profile_approval_guard();
CREATE FUNCTION fn_ty_ps_job_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE tr public.ty_ps_trigger%ROWTYPE;c public.ty_pay_config%ROWTYPE;r public.ty_ps_run%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='触发意图保留历史';END IF;
 SELECT * INTO tr FROM public.ty_ps_trigger WHERE id=NEW.trigger_id;
 IF TG_OP='INSERT'AND tr.status<>'approved'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='触发器未启用';END IF;
 IF TG_OP='UPDATE'THEN
  IF OLD.state<>'queued'OR NEW.state NOT IN('completed','blocked','cancelled')OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['state','revision','run_id','processed_by','processed_at','reason'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','revision','run_id','processed_by','processed_at','reason'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='触发意图不得换来源或重复处理';END IF;
 END IF;
 IF NEW.source_domain='salary_profile'THEN
  SELECT * INTO c FROM public.ty_pay_config WHERE id=NEW.source_id;
  IF c.kind<>'profile'OR c.status<>'approved'OR c.employment_id<>tr.employment_id OR EXISTS(SELECT 1 FROM public.ty_ps_origin WHERE profile_config_id=c.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资脚本产生的参数不得再触发脚本形成递归';END IF;
 END IF;
 IF NEW.run_id IS NOT NULL THEN SELECT * INTO r FROM public.ty_ps_run WHERE id=NEW.run_id;IF r.script_id<>tr.script_id OR r.employment_id<>tr.employment_id OR r.period<>NEW.period THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='任务只能绑定原脚本与原关系预演';END IF;END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_job_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_ps_job FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_job_guard();
-- Source transitions enqueue preview intentions in the same transaction. They
-- never approve a profile, create a wage line, or execute a payment.
CREATE FUNCTION fn_ty_ps_enqueue_time()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF NEW.perspective='employer'AND NEW.current_report_id IS NOT NULL AND(OLD.current_report_id IS DISTINCT FROM NEW.current_report_id OR OLD.head_revision<>NEW.head_revision)THEN
  INSERT INTO public.ty_ps_job(trigger_id,event_key,source_domain,source_id,source_revision,period,report_id,created_by)
  SELECT tr.id,'time:'||NEW.id||':'||NEW.head_revision,'time_report',NEW.current_report_id,NEW.head_revision::text,NEW.period,NEW.current_report_id,tr.created_by
  FROM public.ty_ps_trigger tr JOIN public.ty_ps_script s ON s.id=tr.script_id
  WHERE tr.group_id=NEW.group_id AND tr.company_id=NEW.owner_company_id AND tr.employment_id=NEW.employment_id AND tr.status='approved'AND tr.event_kind='time_report.confirmed'AND s.status='approved'
   AND tr.valid_from<=NEW.period AND(tr.valid_to IS NULL OR tr.valid_to>=(NEW.period+interval'1 month')::date)
   AND s.valid_from<=NEW.period AND(s.valid_to IS NULL OR s.valid_to>=(NEW.period+interval'1 month')::date)
   AND EXISTS(SELECT 1 FROM jsonb_each(s.input_spec) spec WHERE spec.value->>'source'='time_report')
  ON CONFLICT(trigger_id,event_key)DO NOTHING;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_enqueue_time AFTER UPDATE ON ty_time_report_root FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_enqueue_time();
CREATE FUNCTION fn_ty_ps_enqueue_profile()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF NEW.kind='profile'AND NEW.status='approved'AND OLD.status='draft'AND extract(day FROM NEW.valid_from)=1 AND NOT EXISTS(SELECT 1 FROM public.ty_ps_origin WHERE profile_config_id=NEW.id)THEN
  INSERT INTO public.ty_ps_job(trigger_id,event_key,source_domain,source_id,source_revision,period,created_by)
  SELECT tr.id,'profile:'||NEW.id||':'||NEW.revision,'salary_profile',NEW.id,NEW.revision::text,NEW.valid_from,tr.created_by
  FROM public.ty_ps_trigger tr JOIN public.ty_ps_script s ON s.id=tr.script_id
  WHERE tr.group_id=NEW.group_id AND tr.company_id=NEW.company_id AND tr.employment_id=NEW.employment_id AND tr.status='approved'AND tr.event_kind='salary_profile.approved'AND s.status='approved'AND s.system=NEW.system
   AND tr.valid_from<=NEW.valid_from AND(tr.valid_to IS NULL OR tr.valid_to>=(NEW.valid_from+interval'1 month')::date)
   AND NOT EXISTS(SELECT 1 FROM jsonb_each(s.input_spec)spec WHERE spec.value->>'source'='time_report')
  ON CONFLICT(trigger_id,event_key)DO NOTHING;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_ps_enqueue_profile AFTER UPDATE ON ty_pay_config FOR EACH ROW EXECUTE FUNCTION fn_ty_ps_enqueue_profile();
